--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Steam's toasts place themselves in unscaled pixels (xwayland.force_zero_scaling),
-- so they land mid-screen. Pin them to the bottom-right and keep focus on the game.
hl.window_rule({
    name  = "steam-toasts",
    match = { class = "steam", title = "^notificationtoasts.*" },

    float    = true,
    move     = "monitor_w-window_w-6 monitor_h-window_h-6",
    no_focus = true,
})
-- Desktop mode / work mode:
-- empty workspace  -> eww dashboard, no waybar
-- any window on it -> waybar, no dashboard
-- Both commands are safe to repeat (pgrep checks first), so a config reload can't confuse them.
local function update_mode()
  local ws = hl.get_active_workspace()
  if ws and ws.windows == 0 then
    hl.exec_cmd("pkill -x waybar; eww open dashboard")
  else
    hl.exec_cmd("eww close dashboard; pgrep -x waybar || waybar")
  end
end

-- Check 100 ms after the event, so a closing window is already gone from the count
local function update_mode_soon()
  hl.timer(update_mode, { timeout = 100, type = "oneshot" })
end

hl.on("window.open", update_mode_soon)
hl.on("window.close", update_mode_soon)
hl.on("window.move_to_workspace", update_mode_soon)
hl.on("workspace.active", update_mode_soon)

-- My autostart (waybar is started by update_mode, see above)
hl.on("hyprland.start", function ()
  hl.exec_cmd("eww daemon")
  update_mode_soon()
  -- no nm-applet: the waybar network module opens nmtui on click
  hl.exec_cmd("systemctl --user start hyprpolkitagent")
  hl.exec_cmd("hypridle")
  hl.exec_cmd("wl-paste --watch cliphist store")   -- save every copy to the clipboard history
end)

-- Lock the screen with mainMod + L
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("pidof hyprlock || hyprlock"))
-- Move the focused window within the workspace with mainMod + SHIFT + arrows
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "d" }))
